-- ListingAI — Нерухомість
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'listingai.co' OR LOWER(`name`) = LOWER('ListingAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ListingAI', NULL, 'https://www.listingai.co', NULL, NULL, 'AI-набір маркетингу для ріелторів: описи об''єктів для MLS з перевіркою Fair Housing, віртуальний стейджинг, дописи для соцмереж і сайти об''єктів з одного введення.', 'An AI marketing kit for real estate agents: MLS-ready listing descriptions with Fair Housing checks, virtual staging, social posts and listing websites from a single entry.', 'ListingAI допомагає агентам з нерухомості просувати об''єкти без копірайтера й дизайнера. Ви один раз вносите дані про об''єкт, а сервіс готує опис для MLS з перевіркою на відповідність правилам Fair Housing, віртуальний стейджинг і «вечірні» фото, дописи, Reels та Stories для Facebook, Instagram і LinkedIn, сайт і лендинг об''єкта, порівняльний аналіз ринку (CMA), звіти для продавця та огляди місцевого ринку. Є також AI-редактор зображень і генератор ділових портретів. Сервісом користуються понад 30 000 агентів, зокрема з Keller Williams, Compass, RE/MAX і Coldwell Banker. Платні тарифи — від $19 на місяць, є безкоштовний пробний період без картки.', 'ListingAI helps real estate agents market properties without a copywriter or designer. You enter the property details once, and it produces an MLS-ready description checked for Fair Housing compliance, virtual staging and twilight photos, posts, Reels and Stories for Facebook, Instagram and LinkedIn, a listing website and landing page, a comparative market analysis (CMA), seller reports and local market updates. There is also an AI image editor and a headshot generator. More than 30,000 agents use it, including agents at Keller Williams, Compass, RE/MAX and Coldwell Banker. Paid plans start at $19 a month, with a free trial and no card required.', 'Описи для MLS з перевіркою Fair Housing
Віртуальний стейджинг і «вечірні» фото
Контент для соцмереж і сайти об''єктів
CMA та звіти для продавців', 'MLS-ready descriptions with Fair Housing checks
Virtual staging and twilight photos
Social content and listing websites
CMAs and seller reports', 'Агенти з нерухомості та брокерські агенції.', 'Real estate agents and brokerages.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
