-- Rechat — Нерухомість
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rechat.ai' OR LOWER(`name`) = LOWER('Rechat'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rechat', NULL, 'https://rechat.ai', NULL, NULL, 'Операційна система для агентств нерухомості: CRM, маркетинг, супровід угод і AI-асистентка Lucy, яка пише листи, створює контент і сайти об''єктів.', 'An operating system for real estate brokerages: CRM, marketing, deal management and Lucy, an AI assistant that drafts emails and creates content and listing websites.', 'Rechat об''єднує інструменти агентства нерухомості в одній платформі. Studio відповідає за дизайн і публікацію сайтів, листів, дописів, друкованих матеріалів і реклами; People — за контакти, розподіл лідів, задачі, календар і автоматизації; Deals — за супровід угод: об''єкти, пропозиції, чек-листи, електронні підписи через DocuSign і дані MLS. AI-асистентка Lucy розуміє голосові команди, пише листи й контент, генерує сайти об''єктів і пропонує автоматизації. Є застосунки для iOS та Android, інтеграції з Google, Outlook, Zillow і Realtor.com. Ціни не опубліковано — їх надають після демонстрації.', 'Rechat brings a brokerage''s tools together in one platform. Studio handles design and publishing of websites, emails, social posts, print materials and ads; People handles contacts, lead routing, tasks, calendar and automations; Deals handles transactions: listings, offers, checklists, e-signatures via DocuSign and MLS data. Lucy, the AI assistant, understands voice commands, drafts emails and content, generates listing websites and suggests automations. There are iOS and Android apps and integrations with Google, Outlook, Zillow and Realtor.com. Pricing is not published — it is provided after a demo.', 'CRM і розподіл лідів
Маркетинг: сайти, листи, соцмережі, друк
Супровід угод, DocuSign і MLS
AI-асистентка Lucy', 'CRM and lead routing
Marketing: websites, emails, social, print
Deal management, DocuSign and MLS
Lucy AI assistant', 'Брокерські агенції нерухомості та їхні агенти.', 'Real estate brokerages and their agents.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
