-- Restb.ai — Нерухомість
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'restb.ai' OR LOWER(`name`) = LOWER('Restb.ai'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Restb.ai', NULL, 'https://restb.ai', NULL, NULL, 'Комп''ютерний зір для нерухомості: автоматично розпізнає на фото тип кімнати, оздоблення, стан об''єкта й особливості та генерує описи для порталів, оцінювачів і страховиків.', 'Computer vision for real estate: it automatically recognises room types, finishes, property condition and features in photos and generates descriptions for portals, appraisers and insurers.', 'Restb.ai перетворює фото нерухомості на структуровані дані. AI розпізнає тип приміщення, особливості й архітектурний стиль, оцінює стан об''єкта, знаходить схожі й порівнянні об''єкти, генерує підписи та описи, перевіряє фото на водяні знаки й дублікати та оцінює складність об''єкта для оцінювачів. Клієнти — сервіси автоматичної оцінки й інвестори, оцінювачі й інспектори, бази MLS, портали пошуку нерухомості та страхові компанії; серед партнерів — Blackstone, Lemonade і CoreLogic. Ціна індивідуальна й залежить від обсягу.', 'Restb.ai turns property photos into structured data. AI recognises room types, features and architectural styles, assesses property condition, finds similar and comparable properties, generates captions and descriptions, checks photos for watermarks and duplicates and estimates property complexity for appraisers. Customers include automated valuation services and investors, appraisers and inspectors, MLSs, property search portals and insurers; partners include Blackstone, Lemonade and CoreLogic. Pricing is custom and depends on volume.', 'Розпізнавання кімнат, оздоблення й стилю
Оцінка стану об''єкта
Автоматичні описи та підписи
Перевірка фото й пошук порівнянних об''єктів', 'Room, feature and style recognition
Property condition assessment
Automatic descriptions and captions
Photo compliance checks and comparables', 'Портали нерухомості, MLS, оцінювачі, інвестори та страховики.', 'Property portals, MLSs, appraisers, investors and insurers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
