-- Nansen — Крипто та Web3
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'nansen.ai' OR LOWER(`name`) = LOWER('Nansen'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Nansen', NULL, 'https://www.nansen.ai', NULL, NULL, 'Ончейн-аналітика з AI: показує дії «розумних грошей», прибутковість гаманців і токенів, дає AI-сповіщення та глибоке AI-дослідження гаманців.', 'On-chain analytics with AI: it shows what ''smart money'' is doing and wallet and token performance, with AI alerts and deep AI research on wallets.', 'Nansen аналізує дані блокчейнів і мітить гаманці, щоб було видно, що роблять фонди, великі гравці та «розумні гроші». Платформа показує прибутковість окремих гаманців, рух токенів і сегменти власників, дає змогу створювати власні мітки, списки спостереження й сповіщення та вивантажувати дані. AI-функції включають розумні сповіщення, AI-аналіз токенів і глибоке AI-дослідження гаманців, а також API та MCP для розробників. Доступні веб і мобільний застосунок. Тариф Pro коштує $69 на місяць або $49 на місяць при річній оплаті. Nansen — аналітичний інструмент, а не інвестиційна порада; криптоактиви пов''язані з високими ризиками.', 'Nansen analyses blockchain data and labels wallets so you can see what funds, large holders and ''smart money'' are doing. The platform shows the performance of individual wallets, token flows and holder segments and lets you create custom labels, watchlists and alerts and export data. AI features include smart alerts, AI token analysis and deep AI research on wallets, plus API and MCP access for developers. Web and mobile apps are available. The Pro plan costs $69 a month or $49 a month billed annually. Nansen is an analytics tool, not investment advice; crypto assets carry high risk.', 'Мітки гаманців і дані «розумних грошей»
Прибутковість гаманців і рух токенів
AI-сповіщення та AI-дослідження гаманців
API та MCP', 'Wallet labels and smart money data
Wallet PnL and token flows
AI alerts and AI wallet research
API and MCP', 'Криптотрейдери, аналітики та фонди, які досліджують ончейн-дані.', 'Crypto traders, analysts and funds researching on-chain data.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
