INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'finance-legal' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'finance-legal' AND s.`slug` = 'crypto-web3' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'On-chain analytics with AI: it shows what ''smart money'' is doing and wallet and token performance, with AI alerts and deep AI research on wallets.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Nansen analyses blockchain data and labels wallets so you can see what funds, large holders and ''smart money'' are doing. The platform shows the performance of individual wallets, token flows and holder segments and lets you create custom labels, watchlists and alerts and export data. AI features include smart alerts, AI token analysis and deep AI research on wallets, plus API and MCP access for developers. Web and mobile apps are available. The Pro plan costs $69 a month or $49 a month billed annually. Nansen is an analytics tool, not investment advice; crypto assets carry high risk.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Wallet labels and smart money data
Wallet PnL and token flows
AI alerts and AI wallet research
API and MCP', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Crypto traders, analysts and funds researching on-chain data.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Pro', 'Pro', 69.00, 'month', '$49 на місяць при річній оплаті; повний доступ до даних і AI-функцій', '$49 a month billed annually; full data and AI features' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Pro' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Pro', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', '$49 a month billed annually; full data and AI features', 'manual' FROM DUAL WHERE @plan IS NOT NULL;

-- Blockworks Research (Messari) — Крипто та Web3
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'blockworks.com' OR LOWER(`name`) = LOWER('Blockworks Research (Messari)'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Blockworks Research (Messari)', NULL, 'https://blockworks.com', NULL, NULL, 'Дослідницька платформа про криптоактиви, до якої переїхав Messari: профілі активів, дані про раунди фінансування, AI-дайджести, підсумки статей і AI-чат.', 'A crypto research platform that Messari has moved to: asset profiles, fundraising data, AI digests, article summaries and AI chat.', 'Blockworks Research — платформа даних і аналітики про криптоактиви; дослідницький сервіс Messari переїхав саме сюди (старий messari.io доступний з налаштувань акаунта до 31 жовтня 2026 року). Платформа містить профілі активів, дані про раунди фінансування з експортом, ончейн-відстеження та скринери на основі Blockworks AI. AI-інструменти щодня готують дайджести вашого списку спостереження, підсумки статей і новин та відповідають на запитання в AI-чаті. Тарифи: Free — базовий доступ; Pro — $375 на місяць при річній оплаті ($4 500 на рік), зокрема щомісячні дзвінки з аналітиками. Платформа не надає інвестиційних порад.', 'Blockworks Research is a crypto data and analytics platform, and Messari''s research service has moved here (the old messari.io is available from account settings until 31 October 2026). It includes asset profiles, fundraising data with exports, on-chain tracking and screeners powered by Blockworks AI. AI tools prepare daily digests of your watchlist and summaries of articles and news and answer questions in AI chat. Plans: Free — basic access; Pro — $375 a month billed annually ($4,500 a year), including monthly calls with analysts. The platform does not provide investment advice.', 'Профілі криптоактивів і дані про фінансування
AI-дайджести списку спостереження
AI-підсумки статей і новин
AI-чат і скринери', 'Crypto asset profiles and fundraising data
AI watchlist digests
AI article and news summaries
AI chat and screeners', 'Криптоаналітики, фонди й професійні інвестори.', 'Crypto analysts, funds and professional investors.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
